                break
            bands.append((r, next(iter(colors))))

    if horizontal and bands:
        def period_map(period):
            mapping = {}
            for r, color in bands:
                residue = r % period
                if residue in mapping and mapping[residue] != color:
                    return None
                mapping[residue] = color
            return mapping

        period = len(bands)
        mapping = period_map(period)
        if mapping is None:
            candidates = [(p, period_map(p)) for p in range(1, h + 1)
                          if period_map(p) is not None]
            repeated = [(p, m) for p, m in candidates
                        if len({r % p for r, _ in bands}) < len(bands)]
            period, mapping = min(repeated or candidates, key=lambda item: item[0])
        return [[mapping.get(r % period, 0)] * w for r in range(h)]

    points = [(r, c, value) for r, row in enumerate(grid)
              for c, value in enumerate(row) if value]
    if not points:
        return [row[:] for row in grid]

    adjacency = {
        "sum": sum(1 for r, c, value in points
                   if r + 1 < h and c > 0 and grid[r + 1][c - 1] == value),
        "diff": sum(1 for r, c, value in points
                    if r + 1 < h and c + 1 < w and grid[r + 1][c + 1] == value),
    }
    direction = max(adjacency, key=adjacency.get)
    candidates = []
    for period in range(2, min(h, w) + 1):
        counts = defaultdict(Counter)
        for r, c, value in points:
            residue = ((r + c) if direction == "sum" else (c - r)) % period
            counts[residue][value] += 1
        if sum(max(count.values()) for count in counts.values()) == len(points):
            candidates.append((len(counts), -period, period, counts))

    if candidates:
        _, _, period, counts = max(candidates)
    else:
        period = 2
        counts = defaultdict(Counter)
        for r, c, value in points:
            residue = ((r + c) if direction == "sum" else (c - r)) % period
            counts[residue][value] += 1

    mapping = {residue: counts[residue].most_common(1)[0][0]
               for residue in counts}
    default = 3 if any(value == 3 for _, _, value in points) else Counter(
        value for _, _, value in points).most_common(1)[0][0]
    return [[mapping.get(((r + c) if direction == "sum" else (c - r)) % period, default)
